SELECT 
    (COUNT(CASE WHEN Products.Discontinued = '1' THEN 1 END) * 100.0 / COUNT(*)) AS discontinued_proportion
FROM Products;

SELECT SUM(Orders.Freight) AS TotalFreightCost
FROM Orders
WHERE Orders.OrderDate BETWEEN '2020-01-01' AND '2024-12-31';

SELECT 
    (COUNT(CASE WHEN UnitsInStock <= ReorderLevel THEN 1 END) * 1.0 / COUNT(ProductID)) * 100 AS Reorder_Necessity_Percentage
FROM Products;

SELECT COUNT(*) AS ReorderNecessityCount
FROM Products
WHERE UnitsInStock <= ReorderLevel;

SELECT COUNT(*) AS TotalDiscontinuedProducts
FROM Products
WHERE Discontinued BETWEEN '2020-01-01' AND '2024-12-31';

SELECT COUNT(*) AS DiscontinuedCount
FROM Products
WHERE Discontinued BETWEEN '2020-01-01' AND '2024-12-31';

SELECT 
   (COUNT(CASE WHEN Discontinued = 'Y' THEN 1 END) * 100.0 / COUNT(*)) AS discontinued_percentage
FROM Products;

SELECT COUNT(OrderID) AS TotalOrders 
FROM Orders 
WHERE strftime('%Y-%m-%d', OrderDate) BETWEEN '2023-10-01' AND '2023-12-31';

SELECT COUNT(*) AS ProductsNeedingRestock
FROM Products
WHERE UnitsInStock <= ReorderLevel;

SELECT COUNT(DISTINCT CustomerID) AS TotalDistinctCustomers
FROM Orders
WHERE OrderDate >= '2023-01-01' AND OrderDate < '2024-01-01';

SELECT COUNT(*) AS ProductCount
FROM Products
WHERE UnitsInStock <= ReorderLevel;

SELECT SUM(p.UnitPrice * p.UnitsInStock) AS TotalValueBelowReorder
FROM Products p
WHERE p.UnitsInStock < p.ReorderLevel;

SELECT 
    (COUNT(CASE WHEN UnitsInStock <= ReorderLevel THEN 1 END) * 1.0 / COUNT(ProductID)) * 100 AS ReorderNecessityPercentage
FROM Products;
